let language = 'en';
try { language = localStorage.getItem('axel-language') === 'fr' ? 'fr' : 'en'; } catch (_) {}
const locale = () => language === 'en' ? 'en-GB' : 'fr-FR';
const t = text => language === 'en' ? (TRANSLATIONS[text] ?? text) : text;
const copy = (fr,en) => language === 'en' ? en : fr;
// Capture only the static document once. Dynamic content is translated at render time.
const staticCopy = [];
const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
while (walker.nextNode()) {
 const node = walker.currentNode;
 if (!node.parentElement.closest('script,style') && node.textContent.trim()) staticCopy.push([node,node.textContent]);
}
const staticAttributes = [];
document.querySelectorAll('[aria-label],[title],[placeholder],meta[name="description"]').forEach(el => {
 for (const attr of ['aria-label','title','placeholder','content']) if (el.hasAttribute(attr)) staticAttributes.push([el,attr,el.getAttribute(attr)]);
});
function translateStatic() {
 document.documentElement.lang = language;
 staticCopy.forEach(([node,source]) => { node.textContent = source.replace(source.trim(),t(source.trim())); });
 staticAttributes.forEach(([el,attr,source]) => el.setAttribute(attr,t(source)));
 document.querySelectorAll('[data-language]').forEach(button => {
  const selected = button.dataset.language === language;
  button.setAttribute('aria-pressed',String(selected));
  button.classList.toggle('selected',selected);
 });
}
translateStatic();
